import { ExistingThemes } from "@/core/types/existing-themes";
import Card from "@/core/components/primitives/card/card";
import { SecondaryButtonLink, buttonUrlFromCallToAction } from "@/core/components/primitives/parks-button/parks-button";
import styles from "./ad-list-item.module.less";
import { multipleClassNames } from "@/core/helpers/string-helper";
import { CallToAction } from "@/core/types";

export type Props = {
  title: string;
  preamble?: string;
  shortDescriptionInList?: string;
  callToActionButton?: Omit<CallToAction, "asset">;
  componentTheme?: ExistingThemes;
  className?: string;
};

const AdListItem = ({
  title,
  preamble,
  shortDescriptionInList,
  callToActionButton,
  componentTheme,
  className,
}: Props) => {
  const buttonUrl = buttonUrlFromCallToAction(callToActionButton);

  return (
    <div className={multipleClassNames(styles.wrapper, componentTheme, className)}>
      <Card>
        <div className={styles.container}>
          <h2>{title}</h2>
          {preamble && <p className="body-l">{preamble}</p>}
          {shortDescriptionInList && <p>{shortDescriptionInList}</p>}
          {callToActionButton?.title && buttonUrl && (
            <SecondaryButtonLink
              url={buttonUrl}
              label={callToActionButton.title}
              openInNewTab={callToActionButton.openInNewTab}
            />
          )}
        </div>
      </Card>
    </div>
  );
};

export default AdListItem;
